//! `Level.explode` block results vs the real vanilla server classes: `tests/oracle/scenarios/explosion_blocks.txt` (generated by
//! `gen_explosion_blocks.py`) builds random terrain boxes (stone/dirt/obsidian/water/lava/glass/sand/bedrock/..., world bottom),
//! seeds `Level.random`, explodes (radius 0.5..10, fire, block/mob/tnt/none/trigger) and dumps the blocks left. The fixture is the
//! vanilla output (`scripts/entity-oracle.sh`); this test replays the same script on a real `ServerLevel`.
use crate::common;

use mc_core::ident::Identifier;
use mc_core::pos::BlockPos;
use mc_core::random::RandomSource as _;
use mc_data::block::{Block, BlockState};
use mc_game::server::level::ServerLevel;
use mc_game::server::level::level_explode::Explode;
use mc_game::world::level::explosion::ExplosionInteraction;
use mc_game::world::level::{BlockGetter, LevelAccessor};

fn registries() -> mc_game::registry::RegistryAccess {
    static ACCESS: std::sync::OnceLock<mc_game::registry::RegistryAccess> =
        std::sync::OnceLock::new();
    ACCESS
        .get_or_init(|| {
            let _serial = common::SERIAL.lock().unwrap_or_else(|e| e.into_inner());
            let dir = tempfile::tempdir().unwrap();
            let (_, stem) = common::load_world(
                dir.path(),
                mc_world::level_storage::WorldDataConfiguration::DEFAULT,
                true,
            )
            .expect("default world loads");
            stem.registries.composite_access().clone()
        })
        .clone()
}

fn parse_state(text: &str) -> BlockState {
    let (name, props) = match text.split_once('[') {
        Some((n, p)) => (n, Some(p.trim_end_matches(']'))),
        None => (text, None),
    };
    let mut state = Block::by_name(name)
        .unwrap_or_else(|| panic!("block {name}"))
        .default_state();
    for kv in props.into_iter().flat_map(|p| p.split(',')) {
        let (k, v) = kv.split_once('=').unwrap();
        state = state
            .with_property_str(k, v)
            .unwrap_or_else(|| panic!("property {kv} of {text}"));
    }
    state
}

fn serialize(state: BlockState) -> String {
    let mut s = state.block().name().to_string();
    let props: Vec<String> = state
        .values()
        .map(|(d, i)| format!("{}={}", d.name, d.values[i]))
        .collect();
    if !props.is_empty() {
        s.push('[');
        s.push_str(&props.join(","));
        s.push(']');
    }
    s
}

#[test]
fn explosion_block_sets_match_vanilla() {
    let scenario =
        std::fs::read_to_string(common::entity_oracle::scenario_dir().join("explosion_blocks.txt"))
            .unwrap();
    let expected =
        std::fs::read_to_string(common::entity_oracle::fixture_dir().join("explosion_blocks.txt"))
            .unwrap();
    let mut level = ServerLevel::detached(Identifier::parse("minecraft:overworld").unwrap());
    level.registries = registries();
    let mut actual: Vec<String> = Vec::new();
    let i = |s: &str| s.parse::<i32>().unwrap();
    for line in scenario
        .lines()
        .map(str::trim)
        .filter(|l| !l.is_empty() && !l.starts_with('#'))
    {
        let a: Vec<&str> = line.split_whitespace().collect();
        match a[0] {
            "level" => {}
            "note" => actual.push(format!("# {}", line[4..].trim())),
            "fill" => {
                let state = parse_state(a[7]);
                for x in i(a[1]).min(i(a[4]))..=i(a[1]).max(i(a[4])) {
                    for y in i(a[2]).min(i(a[5]))..=i(a[2]).max(i(a[5])) {
                        for z in i(a[3]).min(i(a[6]))..=i(a[3]).max(i(a[6])) {
                            level.set_block_and_update(BlockPos::new(x, y, z), state);
                        }
                    }
                }
            }
            "level_seed" => LevelAccessor::random(&mut level).set_seed(a[1].parse().unwrap()),
            "explode" => {
                let interaction = match *a.last().unwrap() {
                    "none" => ExplosionInteraction::None,
                    "block" => ExplosionInteraction::Block,
                    "mob" => ExplosionInteraction::Mob,
                    "tnt" => ExplosionInteraction::Tnt,
                    "trigger" => ExplosionInteraction::Trigger,
                    other => panic!("{other}"),
                };
                let fire = a.contains(&"fire");
                let (x, y, z, r): (f64, f64, f64, f32) = (
                    a[1].parse().unwrap(),
                    a[2].parse().unwrap(),
                    a[3].parse().unwrap(),
                    a[4].parse().unwrap(),
                );
                level.explode(
                    Explode::new(None, x, y, z, r, interaction).with_fire(fire),
                    &mut [],
                );
            }
            "dump" => {
                let c: Vec<i32> = a[1]
                    .strip_prefix("blocks:")
                    .unwrap()
                    .split(',')
                    .map(|v| v.parse().unwrap())
                    .collect();
                for x in c[0]..=c[3] {
                    for y in c[1]..=c[4] {
                        for z in c[2]..=c[5] {
                            let st = level.get_block_state(BlockPos::new(x, y, z));
                            if !st.is_air() {
                                actual.push(format!("B {x} {y} {z} {}", serialize(st)));
                            }
                        }
                    }
                }
            }
            other => panic!("unsupported scenario command {other}"),
        }
    }
    let expected: Vec<&str> = expected.lines().collect();
    let mut case = String::new();
    let mut diffs = 0;
    for (n, (e, a)) in expected.iter().zip(actual.iter()).enumerate() {
        if e.starts_with('#') {
            case = e.to_string();
        }
        if e != a {
            diffs += 1;
            if diffs <= 10 {
                eprintln!("line {n} ({case}): vanilla `{e}` / ours `{a}`");
            }
        }
    }
    assert_eq!(
        (diffs, expected.len()),
        (0, actual.len()),
        "explosion results differ from vanilla"
    );
}
